const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();

  // Set viewport to A1 portrait dimensions (2339 x 3307 pixels at 96 DPI)
  await page.setViewport({ width: 2339, height: 3307, deviceScaleFactor: 2 });

  const htmlPath = 'file://' + path.resolve(__dirname, 'State-of-Developer-Ecosystem-2024-infographic.html');
  await page.goto(htmlPath, { waitUntil: 'networkidle0' });

  // Wait for fonts and rendering
  await page.waitForTimeout(3000);

  // Export PNG
  const pngBuffer = await page.screenshot({
    type: 'png',
    fullPage: true,
    background: '#0f172a'
  });

  require('fs').writeFileSync(path.join(__dirname, 'final_poster.png'), pngBuffer);
  console.log('PNG exported to final_poster.png');

  await browser.close();
})();

